try:
    import PyQt6  # noqa: F401
except ImportError:
    subprocess.run([sys.executable, "-m", "pip", "install", "PyQt6"],
                   creationflags=0x08000000)  # sans fenêtre console
    import importlib
    importlib.invalidate_caches()
    try:
        import PyQt6  # noqa: F401
    except ImportError:
        try:
            ctypes.windll.user32.MessageBoxW(
                0, "PyQt6 est requis. Installez-le : python -m pip install PyQt6",
                "LGS InstalleX — PyQt6 manquant", 0x10  # MB_ICONERROR
            )
        except Exception:
            print("PyQt6 requis : python -m pip install PyQt6", file=sys.stderr)
        sys.exit(1)
