# ═══════════════════════════════════════════════════════════════════════════════
# VÉRIFICATION DROITS ADMIN
# ═══════════════════════════════════════════════════════════════════════════════

def is_admin() -> bool:
    try:
        return ctypes.windll.shell32.IsUserAnAdmin() != 0
    except Exception:
        return False


def relaunch_as_admin():
    """Relance le script avec élévation UAC.

    Correctifs :
    - sys.argv[0] forcé en chemin ABSOLU (le processus élevé démarre dans
      C:\\Windows\\System32 ; un chemin relatif serait introuvable).
    - Chaque argument mis entre guillemets (sinon un espace dans le chemin,
      ex. « Groupe LGS » ou un profil OneDrive, casse la commande).
    - ShellExecuteW renvoie <= 32 en cas d'échec → on affiche une MessageBox
      au lieu de mourir en silence.
    """
    try:
        script = os.path.abspath(sys.argv[0])
        args   = [script, *sys.argv[1:]]
        params = " ".join(f'"{a}"' for a in args)

        # Relancer l'instance ÉLEVÉE avec pythonw.exe (sans console) plutôt
        # que python.exe : c'est cette instance qui affiche la GUI et reste
        # ouverte, donc c'est sa console qui traînait en arrière-plan.
        launcher = sys.executable
        if os.path.basename(launcher).lower() == "python.exe":
            cand = os.path.join(os.path.dirname(launcher), "pythonw.exe")
            if os.path.exists(cand):
                launcher = cand

        rc = ctypes.windll.shell32.ShellExecuteW(
            None, "runas", launcher, params, None, 1
        )
        if rc <= 32:
            ctypes.windll.user32.MessageBoxW(
                0,
                f"Échec de l'élévation administrateur (code {rc}).\n\n"
                f"Interpréteur : {sys.executable}\nScript : {script}",
                "LGS InstalleX — relance admin",
                0x10,  # MB_ICONERROR
            )
    except Exception as e:
        try:
            ctypes.windll.user32.MessageBoxW(
                0, str(e), "LGS InstalleX — relance admin", 0x10
            )
        except Exception:
            pass
    sys.exit(0)


